# elementary cycles (simple enumeration), rotated to min id
def elementary_cycles(nodes, edges, ids):
    # nodes: list; edges: dict node->list
    order=sorted(nodes, key=lambda n: ids[n])
    cycles=[]
    for i,s in enumerate(order):
        allowed=set(order[i:])
        # dfs for simple paths from s back to s using only allowed nodes
        stack=[s]
        def go(x):
            for y in edges.get(x,[]):
                if y not in allowed: continue
                if y==s: cycles.append(stack+[s])
                elif y not in stack:
                    stack.append(y); go(y); stack.pop()
        go(s)
    return cycles
