	"github.com/deptree-clone/deptree/internal/rust"
)

//go:embed sample-config.yml
var SampleConfig string

const DefaultConfigPath = ".dep-tree.yml"

// Config is the root of the .dep-tree.yml configuration file.
type Config struct {
	Path          string        `yaml:"-"`
	Exclude       []string      `yaml:"exclude"`
	Only          []string      `yaml:"only"`
	UnwrapExports bool          `yaml:"unwrapExports"`
	Check         check.Config  `yaml:"check"`
	Js            js.Config     `yaml:"js"`
	Python        python.Config `yaml:"python"`
	Rust          rust.Config   `yaml:"rust"`
	Golang        golang.Config `yaml:"golang"`
}

func NewConfig(dir string) *Config {
	return &Config{
		Path: dir,
		Check: check.Config{
			Path:    dir,
			Aliases: map[string][]string{},
		},
		Js: js.Config{
			Workspaces:    true,
			TsConfigPaths: true,
		},
	}
}

// ParseConfig loads the configuration from the given path. If path is empty
// the default path is used and a missing file is not considered an error.
func ParseConfig(path string) (*Config, error) {
	isDefault := path == ""
	if isDefault {
		path = DefaultConfigPath
	}
	absPath, err := filepath.Abs(path)
	if err != nil {
		return nil, err
	}
	cfg := NewConfig(filepath.Dir(absPath))

	content, err := os.ReadFile(path)
	if err != nil {
		if isDefault && errors.Is(err, os.ErrNotExist) {
			return cfg, nil
		}
		return nil, err
	}
	decoder := yaml.NewDecoder(bytes.NewReader(content))
	decoder.KnownFields(true)
	if err := decoder.Decode(cfg); err != nil {
		return nil, fmt.Errorf("config file \"%s\" is not a valid yml file: %w", path, err)
	}
	cfg.Check.Path = cfg.Path
	cfg.Check.WhiteListOrder, cfg.Check.BlackListOrder = keyOrder(content)
	return cfg, nil
}

// keyOrder extracts the order in which the allow and deny keys were declared.
func keyOrder(content []byte) ([]string, []string) {
	var root yaml.Node
	if err := yaml.Unmarshal(content, &root); err != nil {
		return nil, nil
	}
	if root.Kind != yaml.DocumentNode || len(root.Content) == 0 {
		return nil, nil
	}
	doc := root.Content[0]
	checkNode := mapGet(doc, "check")
	if checkNode == nil {
		return nil, nil
	}
	return mapKeys(mapGet(checkNode, "allow")), mapKeys(mapGet(checkNode, "deny"))
}

func mapGet(n *yaml.Node, key string) *yaml.Node {
	if n == nil || n.Kind != yaml.MappingNode {
		return nil
	}
	for i := 0; i+1 < len(n.Content); i += 2 {
		if n.Content[i].Value == key {
			return n.Content[i+1]
		}
	}
	return nil
}

func mapKeys(n *yaml.Node) []string {
	if n == nil || n.Kind != yaml.MappingNode {
		return nil
	}
	var keys []string
	for i := 0; i+1 < len(n.Content); i += 2 {
		keys = append(keys, n.Content[i].Value)
	}
	return keys
}
EOF
echo ok"}

