// Package glob implements "doublestar" style glob matching: `*` matches any
// sequence of non separator characters, `**` matches any number of path
// components, `?` matches a single character, `[...]` character classes and
// `{a,b}` alternatives.
package glob

import (
	"os"
	"path/filepath"
	"sort"
	"strings"
	"unicode/utf8"
)

// Match reports whether name matches the provided pattern.
func Match(pattern, name string) bool {
	for _, p := range expandBraces(pattern) {
		if matchSegments(splitPath(p), splitPath(name)) {
			return true
		}
	}
	return false
}

func splitPath(p string) []string {
	return strings.Split(p, "/")
}

