// Package progress renders a small spinner style progress indicator through
// stderr while files are being loaded.
package progress

import (
	"fmt"
	"io"
	"os"
	"strings"
	"time"
	"unicode/utf8"
)

var spinner = []string{"⠋", "⠙", "⠹", "⠸", "⠼", "⠴", "⠦", "⠧", "⠇", "⠏"}

type Bar struct {
	w        io.Writer
	start    time.Time
	maxWidth int
	count    int
	max      int
	desc     string
}

func New() *Bar {
	b := &Bar{w: os.Stderr, start: time.Now(), max: -1}
	// initial blank render, does not register its width
	_, _ = io.WriteString(b.w, "\r"+b.line())
	return b
}

func (b *Bar) spin() string {
	idx := int(time.Since(b.start)/(100*time.Millisecond)) % len(spinner)
	return spinner[idx]
}

func (b *Bar) rate() string {
	if b.count == 0 {
		return "0 it/hr"
	}
	secs := time.Since(b.start).Seconds()
	if secs <= 0 {
		secs = 1e-6
	}
	r := float64(b.count) / secs
	if r < 1.0/60 {
		return fmt.Sprintf("%d it/hr", int(r*3600))
	} else if r < 1 {
		return fmt.Sprintf("%d it/min", int(r*60))
	}
	return fmt.Sprintf("%d it/s", int(r))
}

func (b *Bar) line() string {
	elapsed := int(time.Since(b.start).Seconds())
	if b.max < 0 {
		return fmt.Sprintf("%s %s (%s) [%ds] ", b.spin(), b.desc, b.rate(), elapsed)
	}
	return fmt.Sprintf("%s (%d/%d) %s (%s) [%ds] ", b.spin(), b.count, b.max, b.desc, b.rate(), elapsed)
}

func (b *Bar) clear() {
	if b.maxWidth == 0 {
		return
	}
	_, _ = io.WriteString(b.w, "\r"+strings.Repeat(" ", b.maxWidth)+"\r")
}

func (b *Bar) render() {
	b.clear()
	l := b.line()
	_, _ = io.WriteString(b.w, "\r"+l)
	if w := utf8.RuneCountInString(l); w > b.maxWidth {
		b.maxWidth = w
	}
}

// Loaded must be called each time a file was loaded, with the current amount
// of known files.
func (b *Bar) Loaded(total int) {
	b.count++
	if b.count == 1 {
		b.render()
		b.clear()
		b.maxWidth = 0
	}
	b.max = total
	b.desc = "Loading Files..."
	b.render()
	b.render()
}

// Finish renders the final state.
func (b *Bar) Finish(total int) {
	b.max = total
	b.desc = "Finished loading"
	b.render()
	b.render()
	_, _ = io.WriteString(b.w, "\n")
}
