}

func (g *Graph) Get(path string) *Node {
	return g.byPath[path]
}

func (g *Graph) add(path string) *Node {
	n := &Node{ID: language.ID(path), Path: path}
	g.byPath[path] = n
	g.Nodes = append(g.Nodes, n)
	return n
}

func (g *Graph) addEdge(from, to *Node) {
	if from == to {
		return
	}
	for _, c := range from.Children {
		if c == to {
			return
		}
	}
	from.Children = append(from.Children, to)
	to.Parents = append(to.Parents, from)
}

// Edge is a directed edge between two nodes.
type Edge struct {
	From, To *Node
}

// DFSCycles runs a depth first search starting at the provided nodes and
// returns the set of back edges (cyclic edges) in discovery order, together
// with the cycles they close.
func DFSCycles(starts []*Node, visited map[*Node]bool) ([]Edge, [][]*Node) {
	var edges []Edge
	var cycles [][]*Node
	onStack := map[*Node]int{}
	var stack []*Node
	var dfs func(n *Node)
	dfs = func(n *Node) {
		visited[n] = true
		onStack[n] = len(stack)
		stack = append(stack, n)
		for _, c := range n.Children {
			if idx, ok := onStack[c]; ok {
				edges = append(edges, Edge{n, c})
				cycle := append([]*Node{}, stack[idx:]...)
				cycle = append(cycle, c)
				cycles = append(cycles, cycle)
			} else if !visited[c] {
				dfs(c)
			}
		}
		stack = stack[:len(stack)-1]
		delete(onStack, n)
	}
	for _, s := range starts {
		if !visited[s] {
			dfs(s)
		}
	}
	return edges, cycles
}

// ElementaryCycles returns all the elementary cycles in the graph. Each cycle
// starts at the node with the lowest ID and ends with that same node. Cycles
// are sorted by their starting node's ID.
func ElementaryCycles(nodes []*Node, skip map[Edge]bool) [][]*Node {
	order := append([]*Node{}, nodes...)
	sort.SliceStable(order, func(i, j int) bool { return order[i].ID < order[j].ID })
	inGraph := map[*Node]bool{}
	for _, n := range nodes {
		inGraph[n] = true
	}
	var cycles [][]*Node
	for i, s := range order {
		allowed := map[*Node]bool{}
		for _, n := range order[i:] {
			allowed[n] = true
		}
		// prune to the strongly connected part reachable from s and that can reach s
		reach := map[*Node]bool{}
		var fwd func(n *Node)
		fwd = func(n *Node) {
			reach[n] = true
			for _, c := range n.Children {
				if allowed[c] && !reach[c] && !skip[Edge{n, c}] {
					fwd(c)
				}
			}
		}
		fwd(s)
		back := map[*Node]bool{}
		var bwd func(n *Node)
		bwd = func(n *Node) {
			back[n] = true
			for _, p := range n.Parents {
				if allowed[p] && reach[p] && !back[p] && !skip[Edge{p, n}] {
					bwd(p)
				}
			}
		}
		bwd(s)
		stack := []*Node{s}
		onStack := map[*Node]bool{s: true}
		var walk func(n *Node)
		walk = func(n *Node) {
			for _, c := range n.Children {
				if !inGraph[c] || !allowed[c] || !back[c] || skip[Edge{n, c}] {
					continue
				}
				if c == s {
					cycle := append([]*Node{}, stack...)
					cycle = append(cycle, s)
					cycles = append(cycles, cycle)
				} else if !onStack[c] {
					onStack[c] = true
					stack = append(stack, c)
					walk(c)
					stack = stack[:len(stack)-1]
					delete(onStack, c)
				}
			}
		}
		walk(s)
	}
	return cycles
}
