package graph

import (
	"github.com/deptree-clone/deptree/internal/language"
	"github.com/deptree-clone/deptree/internal/progress"
)

// Load builds the graph starting from the provided entrypoints. Each
// entrypoint is fully explored (breadth first) before moving to the next one.
func Load(entrypoints []string, lang language.Language, ignore func(string) bool, bar *progress.Bar) (*Graph, error) {
	g := New()
	total := 0
	for _, e := range entrypoints {
		if ignore(e) {
			continue
		}
		if g.Get(e) == nil {
			total++
		}
	}
	for _, e := range entrypoints {
		if ignore(e) || g.Get(e) != nil {
			continue
		}
		queue := []*Node{g.add(e)}
		for len(queue) > 0 {
			n := queue[0]
			queue = queue[1:]
			res, err := lang.Load(n.Path)
			if err != nil {
				return nil, err
			}
			n.Info = res.Info
			n.Errors = res.Errors
			for _, dep := range res.Deps {
				if ignore(dep) {
					continue
				}
				child := g.Get(dep)
				if child == nil {
					child = g.add(dep)
					queue = append(queue, child)
					total++
				}
				g.addEdge(n, child)
			}
			if bar != nil {
				bar.Loaded(total)
			}
		}
	}
	if bar != nil {
		if total == 0 {
			total = len(entrypoints)
		}
		bar.Finish(total)
	}
	return g, nil
}
