package js

type tokenKind int

const (
	tIdent tokenKind = iota
	tString
	tPunct
	tOther
)

type token struct {
	kind  tokenKind
	value string
}

func isIdentStart(c byte) bool {
	return c == '_' || c == '$' || (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z')
}

func isIdentChar(c byte) bool {
	return isIdentStart(c) || (c >= '0' && c <= '9')
}

// scanString tries to scan a quoted string starting at i. Returns the end
// index (exclusive) or -1 if the string is not terminated.
func scanString(src string, i int) int {
	q := src[i]
	j := i + 1
	for j < len(src) {
		c := src[j]
		if c == '\\' {
			j += 2
			continue
		}
		if c == q {
			return j + 1
		}
		j++
	}
	return -1
}

func unquote(s string) string {
	inner := s[1 : len(s)-1]
	out := make([]byte, 0, len(inner))
	for i := 0; i < len(inner); i++ {
		c := inner[i]
		if c == '\\' && i+1 < len(inner) {
			i++
			switch inner[i] {
			case 'n':
				out = append(out, '\n')
			case 't':
				out = append(out, '\t')
			case 'r':
				out = append(out, '\r')
			default:
				out = append(out, inner[i])
			}
			continue
		}
		out = append(out, c)
	}
	return string(out)
}

func tokenize(src string) []token {
	var tokens []token
	i := 0
	n := len(src)
	for i < n {
		c := src[i]
		switch {
		case c == ' ' || c == '\t' || c == '\n' || c == '\r' || c == '\f' || c == '\v':
			i++
		case c == '/' && i+1 < n && src[i+1] == '/':
			for i < n && src[i] != '\n' {
				i++
			}
		case c == '/' && i+1 < n && src[i+1] == '*':
			end := -1
			for j := i + 2; j+1 < n; j++ {
				if src[j] == '*' && src[j+1] == '/' {
					end = j + 2
					break
				}
			}
			if end < 0 {
				tokens = append(tokens, token{tPunct, "/"})
				i++
			} else {
				i = end
			}
		case c == '\'' || c == '"' || c == '`':
			end := scanString(src, i)
			if end < 0 {
				tokens = append(tokens, token{tPunct, string(c)})
				i++
			} else {
				tokens = append(tokens, token{tString, src[i:end]})
				i = end
			}
		case isIdentStart(c):
			j := i + 1
			for j < n && isIdentChar(src[j]) {
				j++
			}
			tokens = append(tokens, token{tIdent, src[i:j]})
			i = j
		case c >= '0' && c <= '9':
			j := i + 1
			for j < n && (isIdentChar(src[j]) || src[j] == '.') {
				j++
			}
			tokens = append(tokens, token{tOther, src[i:j]})
			i = j
		default:
			if c >= 0x80 {
				// consume a whole utf8 sequence as one token
				j := i + 1
				for j < n && src[j]&0xC0 == 0x80 {
					j++
				}
				tokens = append(tokens, token{tOther, src[i:j]})
				i = j
			} else {
				tokens = append(tokens, token{tPunct, string(c)})
				i++
			}
		}
	}
	return tokens
}
