cat > internal/js/parser.go <<'EOF'
package js

// parser extracts the import paths of a token stream.
type parser struct {
	toks []token
}

func (p *parser) at(i int) *token {
	if i < len(p.toks) {
		return &p.toks[i]
	}
	return nil
}

func (p *parser) isIdent(i int, v string) bool {
	t := p.at(i)
	return t != nil && t.kind == tIdent && t.value == v
}

func (p *parser) isAnyIdent(i int) bool {
	t := p.at(i)
	return t != nil && t.kind == tIdent
}

func (p *parser) isPunct(i int, v string) bool {
	t := p.at(i)
	return t != nil && t.kind == tPunct && t.value == v
}

func (p *parser) isString(i int) bool {
	t := p.at(i)
	return t != nil && t.kind == tString
}

// namedItems matches `{ item (, item)* ,? }`. Returns the index after the
// closing brace or -1.
func (p *parser) namedItems(i int, allowType bool) int {
	if !p.isPunct(i, "{") {
		return -1
	}
	i++
	count := 0
	for {
		j := p.item(i, allowType)
		if j < 0 {
			break
		}
		count++
		i = j
		if p.isPunct(i, ",") {
			i++
			continue
		}
		break
	}
	if count == 0 || !p.isPunct(i, "}") {
		return -1
	}
	return i + 1
}

func (p *parser) item(i int, allowType bool) int {
	if allowType && p.isIdent(i, "type") && p.isAnyIdent(i+1) {
		if j := p.itemNoType(i + 1); j >= 0 {
			return j
		}
	}
	return p.itemNoType(i)
}

func (p *parser) itemNoType(i int) int {
	if !p.isAnyIdent(i) {
		return -1
	}
	i++
	if p.isIdent(i, "as") {
		if p.isAnyIdent(i + 1) {
			return i + 2
		}
		return -1
	}
	return i
}

func (p *parser) namespace(i int) int {
	if !p.isPunct(i, "*") {
		return -1
	}
	i++
	if p.isIdent(i, "as") {
		if p.isAnyIdent(i + 1) {
			return i + 2
		}
		return -1
	}
	return i
}

// importClause matches the part between `import` and `from`.
func (p *parser) importClause(i int) int {
	if j := p.namespace(i); j >= 0 {
		return j
	}
	if j := p.namedItems(i, true); j >= 0 {
		return j
	}
	if p.isAnyIdent(i) {
		j := i + 1
		if p.isPunct(j, ",") {
			if k := p.namespace(j + 1); k >= 0 {
				return k
			}
			if k := p.namedItems(j+1, true); k >= 0 {
				return k
			}
			return -1
		}
		return j
	}
	return -1
}

// matchImport tries to match an import statement at i. Returns the index
// after the statement and the imported path.
func (p *parser) matchImport(i int) (int, string, bool) {
	if !p.isIdent(i, "import") {
		return 0, "", false
	}
	// dynamic import
	if p.isPunct(i+1, "(") && p.isString(i+2) && p.isPunct(i+3, ")") {
		return i + 4, unquote(p.toks[i+2].value), true
	}
	try := func(j int) (int, string, bool) {
		if p.isString(j) {
			return j + 1, unquote(p.toks[j].value), true
		}
		k := p.importClause(j)
		if k >= 0 && p.isIdent(k, "from") && p.isString(k+1) {
			return k + 2, unquote(p.toks[k+1].value), true
		}
		return 0, "", false
	}
	if p.isIdent(i+1, "type") {
		if end, path, ok := try(i + 2); ok {
			return end, path, ok
		}
	}
	return try(i + 1)
}

func (p *parser) matchExport(i int) (int, string, bool) {
	if !p.isIdent(i, "export") {
		return 0, "", false
	}
	j := p.namespace(i + 1)
	if j < 0 {
		j = p.namedItems(i+1, false)
	}
	if j >= 0 && p.isIdent(j, "from") && p.isString(j+1) {
		return j + 2, unquote(p.toks[j+1].value), true
	}
	return 0, "", false
}

func (p *parser) matchRequire(i int) (int, string, bool) {
	if p.isIdent(i, "require") && p.isPunct(i+1, "(") && p.isString(i+2) && p.isPunct(i+3, ")") {
		return i + 4, unquote(p.toks[i+2].value), true
	}
	return 0, "", false
}

// ParseImports returns the import paths found in the provided source code.
func ParseImports(src string) []string {
	p := &parser{toks: tokenize(src)}
	var imports []string
	i := 0
	for i < len(p.toks) {
		if end, path, ok := p.matchImport(i); ok {
			imports = append(imports, path)
			i = end
			continue
		}
		if end, path, ok := p.matchExport(i); ok {
			imports = append(imports, path)
			i = end
			continue
		}
		if end, path, ok := p.matchRequire(i); ok {
			imports = append(imports, path)
			i = end
			continue
		}
		i++
	}
	return imports
}
