var extensions = []string{".js", ".ts", ".tsx", ".jsx", ".mjs", ".cjs"}

func isSupportedExt(ext string) bool {
	for _, e := range extensions {
		if e == ext {
			return true
		}
	}
	return false
}

// resolvePath resolves an absolute path without extension or with a
// replaceable extension to an existing file.
func resolvePath(p string) string {
	if utils.DirExists(p) {
		for _, ext := range extensions {
			candidate := filepath.Join(p, "index"+ext)
			if utils.FileExists(candidate) {
				return candidate
			}
		}
		return ""
	}
	ext := filepath.Ext(p)
	if isSupportedExt(ext) {
		if utils.FileExists(p) {
			return p
		}
		base := strings.TrimSuffix(p, ext)
		for _, e := range extensions {
			if utils.FileExists(base + e) {
				return base + e
			}
		}
		return ""
	}
	for _, e := range extensions {
		if utils.FileExists(p + e) {
			return p + e
		}
	}
	return ""
}

type packageJson struct {
	Name       string      `json:"name"`
	Main       string      `json:"main"`
	Workspaces interface{} `json:"workspaces"`
}

type pkgJsonResult struct {
	pkg *packageJson
	err error
}

var (
	pkgJsonCache   = map[string]*pkgJsonResult{}
	pkgJsonCacheMu sync.Mutex
)

// readPackageJson reads and parses the package.json in dir. Returns nil, nil
// if there is no package.json file.
func readPackageJson(dir string) (*packageJson, error) {
	pkgJsonCacheMu.Lock()
	defer pkgJsonCacheMu.Unlock()
	if r, ok := pkgJsonCache[dir]; ok {
		return r.pkg, r.err
	}
	path := filepath.Join(dir, "package.json")
	content, err := os.ReadFile(path)
	if err != nil {
		pkgJsonCache[dir] = &pkgJsonResult{}
		return nil, nil
	}
	var pkg packageJson
	if err := json.Unmarshal(content, &pkg); err != nil {
		err = fmt.Errorf("error parsing \"%s\": %w", path, err)
		pkgJsonCache[dir] = &pkgJsonResult{err: err}
		return nil, err
	}
	pkgJsonCache[dir] = &pkgJsonResult{pkg: &pkg}
	return &pkg, nil
}

type packageRoot struct {
	dir  string
	name string
}

var packageRootCache = map[string]*packageRoot{}

// findPackageRoot finds the closest parent folder with a valid package.json
// that declares a name.
func findPackageRoot(dir string) *packageRoot {
	if r, ok := packageRootCache[dir]; ok {
		return r
	}
	var result *packageRoot
	pkg, err := readPackageJson(dir)
	if err == nil && pkg != nil && pkg.Name != "" {
		result = &packageRoot{dir: dir, name: pkg.Name}
	} else {
		parent := filepath.Dir(dir)
		if parent != dir {
			result = findPackageRoot(parent)
		}
	}
	packageRootCache[dir] = result
	return result
}

type workspace struct {
	name string
	dir  string
}

type workspacesResult struct {
	ws  []workspace
	err error
}

var workspacesCache = map[string]*workspacesResult{}

func workspacePatterns(raw interface{}) ([]string, bool) {
	toList := func(v interface{}) ([]string, bool) {
		arr, ok := v.([]interface{})
		if !ok {
			return nil, false
		}
		var out []string
		for _, e := range arr {
			if s, ok := e.(string); ok {
				out = append(out, s)
			}
		}
		return out, true
	}
	switch v := raw.(type) {
	case []interface{}:
		return toList(v)
	case map[string]interface{}:
		if p, ok := v["packages"]; ok {
			return toList(p)
		}
	}
	return nil, false
}

// findWorkspaces walks up from dir looking for a package.json declaring
// workspaces.
func findWorkspaces(dir string) ([]workspace, error) {
	if r, ok := workspacesCache[dir]; ok {
		return r.ws, r.err
	}
	var ws []workspace
	pkg, err := readPackageJson(dir)
	if err == nil {
		var patterns []string
		hasWorkspaces := false
		if pkg != nil && pkg.Workspaces != nil {
			patterns, hasWorkspaces = workspacePatterns(pkg.Workspaces)
		}
		if hasWorkspaces {
			ws, err = loadWorkspaces(dir, patterns)
		} else {
			parent := filepath.Dir(dir)
			if parent != dir {
				ws, err = findWorkspaces(parent)
			}
		}
	}
	workspacesCache[dir] = &workspacesResult{ws, err}
	return ws, err
}

func loadWorkspaces(root string, patterns []string) ([]workspace, error) {
	var ws []workspace
	for _, pattern := range patterns {
		if pattern == "" || strings.HasPrefix(pattern, "./") || strings.HasPrefix(pattern, "/") || strings.Contains(pattern, "//") {
			continue
		}
		for _, match := range glob.Glob(filepath.Join(root, pattern)) {
			if !utils.DirExists(match) {
				continue
			}
			if !utils.FileExists(filepath.Join(match, "package.json")) {
				continue
			}
			pkg, err := readPackageJson(match)
			if err != nil {
				return nil, err
			}
			ws = append(ws, workspace{name: pkg.Name, dir: match})
		}
	}
	return ws, nil
}

func resolveWorkspaceIndex(dir string) string {
	base := dir
	if utils.DirExists(filepath.Join(dir, "src")) {
		base = filepath.Join(dir, "src")
	}
	for _, ext := range extensions {
		candidate := filepath.Join(base, "index"+ext)
		if utils.FileExists(candidate) {
			return candidate
		}
	}
	return ""
}

// resolveWorkspace returns the resolved path, whether some workspace matched,
// and an error.
func resolveWorkspace(fileDir string, importPath string) (string, bool, error) {
	ws, err := findWorkspaces(fileDir)
	if err != nil {
		return "", true, err
	}
	for _, w := range ws {
		if w.name == "" {
			continue
		}
		if importPath == w.name || importPath == w.name+"/" {
			if r := resolveWorkspaceIndex(w.dir); r != "" {
				return r, true, nil
			}
			return "", true, fmt.Errorf("workspace '%s' has no index file", w.dir)
		}
		if strings.HasPrefix(importPath, w.name+"/") {
			rest := importPath[len(w.name)+1:]
			full := filepath.Join(w.dir, rest)
			if r := resolvePath(full); r != "" {
				return r, true, nil
			}
			return "", true, fmt.Errorf("path '%s' matched workspace '%s', but no file '%s' does not exist", importPath, w.name, full)
		}
	}
	return "", false, nil
}
