package js

import (
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"
	"sort"
	"strings"
)

type CompilerOptions struct {
	BaseUrl string              `json:"baseUrl"`
	Paths   map[string][]string `json:"paths"`
}

type TsConfig struct {
	CompilerOptions CompilerOptions `json:"compilerOptions"`
}

type tsConfigResult struct {
	cfg       *TsConfig
	pathOrder []string
	err       error
}

var tsConfigCache = map[string]*tsConfigResult{}

// pathsOrder extracts the declaration order of the "paths" keys.
func pathsOrder(std []byte) []string {
	dec := json.NewDecoder(strings.NewReader(string(std)))
	var keys []string
	depth := 0
	inCompilerOptions := false
	inPaths := false
	expectKey := false
	var stack []bool // true if object
	pendingKey := ""
	for {
		tok, err := dec.Token()
		if err != nil {
			break
		}
		switch v := tok.(type) {
		case json.Delim:
			switch v {
			case '{':
				if depth == 1 && pendingKey == "compilerOptions" {
					inCompilerOptions = true
				} else if depth == 2 && inCompilerOptions && pendingKey == "paths" {
					inPaths = true
				}
				depth++
				stack = append(stack, true)
				expectKey = true
			case '[':
				depth++
				stack = append(stack, false)
				expectKey = false
			case '}', ']':
				depth--
				stack = stack[:len(stack)-1]
				if depth == 2 && inPaths && v == '}' {
					inPaths = false
				}
				if depth == 1 && inCompilerOptions && v == '}' {
					inCompilerOptions = false
				}
				expectKey = len(stack) > 0 && stack[len(stack)-1]
			}
			pendingKey = ""
			continue
		case string:
			if expectKey && len(stack) > 0 && stack[len(stack)-1] {
				pendingKey = v
				if inPaths && depth == 3 {
					keys = append(keys, v)
				}
				expectKey = false
				continue
			}
		}
		pendingKey = ""
		expectKey = len(stack) > 0 && stack[len(stack)-1]
	}
	return keys
}

func loadTsConfig(dir string) (*TsConfig, []string, error) {
	if r, ok := tsConfigCache[dir]; ok {
		return r.cfg, r.pathOrder, r.err
	}
	path := filepath.Join(dir, "tsconfig.json")
	content, err := os.ReadFile(path)
	if err != nil {
		tsConfigCache[dir] = &tsConfigResult{}
		return nil, nil, nil
	}
	r := &tsConfigResult{}
	std, err := standardize(content)
	if err == nil {
		var cfg TsConfig
		err = json.Unmarshal(std, &cfg)
		if err == nil {
			r.cfg = &cfg
			r.pathOrder = pathsOrder(std)
			// make sure all keys are present
			if len(r.pathOrder) != len(cfg.CompilerOptions.Paths) {
				r.pathOrder = nil
				for k := range cfg.CompilerOptions.Paths {
					r.pathOrder = append(r.pathOrder, k)
				}
				sort.Strings(r.pathOrder)
			}
		}
	}
	if err != nil {
		r.err = fmt.Errorf("found TypeScript config file in %s but there was an error reading it: %w", path, err)
	}
	tsConfigCache[dir] = r
	return r.cfg, r.pathOrder, r.err
}

// resolveTsConfig resolves a non relative import using the tsconfig.json
// baseUrl and paths options.
func resolveTsConfig(rootDir string, importPath string) (string, error) {
	cfg, order, err := loadTsConfig(rootDir)
	if err != nil {
		return "", err
	}
	if cfg == nil {
		return "", nil
	}
	base := filepath.Join(rootDir, cfg.CompilerOptions.BaseUrl)
	if r := resolvePath(filepath.Join(base, importPath)); r != "" {
		return r, nil
	}
	for _, pattern := range order {
		targets := cfg.CompilerOptions.Paths[pattern]
		prefix := strings.ReplaceAll(pattern, "*", "")
		if !strings.HasPrefix(importPath, prefix) {
			continue
		}
		var tried []string
		for _, target := range targets {
			targetPrefix := strings.ReplaceAll(target, "*", "")
			newPath := filepath.Join(base, strings.ReplaceAll(importPath, prefix, targetPrefix))
			if r := resolvePath(newPath); r != "" {
				return r, nil
			}
			tried = append(tried, newPath)
		}
		if len(tried) > 0 {
			return "", fmt.Errorf("import '%s' was matched to path '%s' in tscofing's paths option, but the resolved path did not match an existing file", importPath, strings.Join(tried, "', '"))
		}
	}
	return "", nil
}
EOF
