package cmd

import (
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"strings"

	"github.com/deptree-clone/deptree/internal/config"
	"github.com/deptree-clone/deptree/internal/glob"
	"github.com/deptree-clone/deptree/internal/golang"
	"github.com/deptree-clone/deptree/internal/js"
	"github.com/deptree-clone/deptree/internal/language"
	"github.com/deptree-clone/deptree/internal/python"
	"github.com/deptree-clone/deptree/internal/rust"
	"github.com/deptree-clone/deptree/internal/utils"
)

func absPattern(cwd, pattern string) string {
	if filepath.IsAbs(pattern) {
		return pattern
	}
	if strings.HasSuffix(pattern, "/") {
		return cwd + "/" + pattern
	}
	return filepath.Join(cwd, pattern)
}

// filesFromArgs expands the glob patterns provided by the user into
// absolute file paths.
func filesFromArgs(args []string) ([]string, error) {
	cwd, err := os.Getwd()
	if err != nil {
		return nil, err
	}
	var result []string
	seen := map[string]bool{}
	for _, arg := range args {
		matches := glob.Glob(absPattern(cwd, arg))
		if len(matches) == 0 {
			return nil, fmt.Errorf("%s does not match with any existing file", arg)
		}
		for _, m := range matches {
			if utils.DirExists(m) {
				continue
			}
			if !seen[m] {
				seen[m] = true
				result = append(result, m)
			}
		}
	}
	if len(result) == 0 {
		return nil, errors.New("no valid files where provided")
	}
	return result, nil
}

func loadConfig() (*config.Config, error) {
	cfg, err := config.ParseConfig(configPath)
	if err != nil {
		return nil, err
	}
	cfg.UnwrapExports = cfg.UnwrapExports || unwrapExports
	return cfg, nil
}

type ignorer struct {
	exclude []string
	only    []string
}

func newIgnorer(cfg *config.Config) *ignorer {
	cwd, _ := os.Getwd()
	ig := &ignorer{}
	for _, e := range cfg.Exclude {
		ig.exclude = append(ig.exclude, absPattern(cfg.Path, e))
	}
	for _, e := range excludeFlags {
		ig.exclude = append(ig.exclude, absPattern(cwd, e))
	}
	for _, o := range cfg.Only {
		ig.only = append(ig.only, absPattern(cfg.Path, o))
	}
	for _, o := range onlyFlags {
		ig.only = append(ig.only, absPattern(cwd, o))
	}
	return ig
}

func (ig *ignorer) Ignore(path string) bool {
	for _, e := range ig.exclude {
		if glob.Match(e, path) {
			return true
		}
	}
	if len(ig.only) > 0 {
		for _, o := range ig.only {
			if glob.Match(o, path) {
				return false
			}
		}
		return true
	}
	return false
}

type langKind int

const (
	langNone langKind = iota
	langJs
	langPython
	langRust
	langGo
)

func kindOf(path string) langKind {
	ext := strings.TrimPrefix(filepath.Ext(path), ".")
	for _, e := range js.Extensions {
		if e == ext {
			return langJs
		}
	}
	switch ext {
	case "py":
		return langPython
	case "rs":
		return langRust
	case "go":
		return langGo
	}
	return langNone
}

// inferLang selects the language with the most files among the provided ones.
func inferLang(files []string, cfg *config.Config) (language.Language, error) {
	counts := map[langKind]int{}
	var order []langKind
	for _, f := range files {
		k := kindOf(f)
		if k == langNone {
			continue
		}
		if counts[k] == 0 {
			order = append(order, k)
		}
		counts[k]++
	}
	best := langNone
	for _, k := range order {
		if best == langNone || counts[k] > counts[best] {
			best = k
		}
	}
	var first string
	for _, f := range files {
		if kindOf(f) == best {
			first = f
			break
		}
	}
	switch best {
	case langJs:
		return js.NewLanguage(), nil
	case langPython:
		return python.NewLanguage(first, &cfg.Python)
	case langRust:
		return rust.NewLanguage(first)
	case langGo:
		return golang.NewLanguage(first)
	}
	return nil, errors.New("none of the provided files belong to the a supported language")
}
