		for _, o := range ig.only {
			if glob.Match(o, path) {
				return false
			}
		}
		return true
	}
	return false
}

type langKind int

const (
	langNone langKind = iota
	langJs
	langPython
	langRust
	langGo
)

func kindOf(path string) langKind {
	ext := strings.TrimPrefix(filepath.Ext(path), ".")
	for _, e := range js.Extensions {
		if e == ext {
			return langJs
		}
	}
	switch ext {
	case "py":
		return langPython
	case "rs":
		return langRust
	case "go":
		return langGo
	}
	return langNone
}

// inferLang selects the language with the most files among the provided ones.
func inferLang(files []string, cfg *config.Config) (language.Language, error) {
	counts := map[langKind]int{}
	var order []langKind
	for _, f := range files {
		k := kindOf(f)
		if k == langNone {
			continue
		}
		if counts[k] == 0 {
			order = append(order, k)
		}
		counts[k]++
	}
	best := langNone
	for _, k := range order {
		if best == langNone || counts[k] > counts[best] {
			best = k
		}
	}
	var first string
	for _, f := range files {
		if kindOf(f) == best {
			first = f
			break
		}
	}
	switch best {
	case langJs:
		return js.NewLanguage(), nil
	case langPython:
		return python.NewLanguage(first, &cfg.Python)
	case langRust:
		return rust.NewLanguage(first)
	case langGo:
		return golang.NewLanguage(first)
	}
	return nil, errors.New("none of the provided files belong to the a supported language")
}
