type structuredTree struct {
	Tree                 map[string]interface{} `json:"tree"`
	CircularDependencies [][]string             `json:"circularDependencies"`
	Errors               map[string][]string    `json:"errors"`
}

// RenderJson renders the tree starting at entry in json format.
func RenderJson(g *graph.Graph, entry *graph.Node) (string, error) {
	cyclicEdges, cycles := graph.DFSCycles([]*graph.Node{entry}, map[*graph.Node]bool{})
	cyclic := map[graph.Edge]bool{}
	for _, e := range cyclicEdges {
		cyclic[e] = true
	}
	var build func(n *graph.Node) interface{}
	build = func(n *graph.Node) interface{} {
		var children map[string]interface{}
		for _, c := range n.Children {
			if cyclic[graph.Edge{From: n, To: c}] {
				continue
			}
			if children == nil {
				children = map[string]interface{}{}
			}
			children[c.Name()] = build(c)
		}
		if children == nil {
			return nil
		}
		return children
	}
	st := structuredTree{
		Tree:                 map[string]interface{}{entry.Name(): build(entry)},
		CircularDependencies: [][]string{},
		Errors:               map[string][]string{},
	}
	for _, cycle := range cycles {
		var names []string
		for _, n := range cycle {
			names = append(names, n.Name())
		}
		st.CircularDependencies = append(st.CircularDependencies, names)
	}
	for _, n := range g.Nodes {
		if len(n.Errors) == 0 {
			continue
		}
		for _, err := range n.Errors {
			st.Errors[n.Name()] = append(st.Errors[n.Name()], err.Error())
		}
	}
	out, err := json.MarshalIndent(st, "", "  ")
	return string(out), err
}
