	var result []string
	for _, p := range patterns {
		if alias, ok := c.Aliases[p]; ok {
			result = append(result, alias...)
		} else {
			result = append(result, p)
		}
	}
	return result
}

func orderedKeys[V any](m map[string]V, order []string) []string {
	var keys []string
	seen := map[string]bool{}
	for _, k := range order {
		if _, ok := m[k]; ok && !seen[k] {
			keys = append(keys, k)
			seen[k] = true
		}
	}
	var rest []string
	for k := range m {
		if !seen[k] {
			rest = append(rest, k)
		}
	}
	sort.Strings(rest)
	return append(keys, rest...)
}

func (c *Config) match(pattern, path string) bool {
	return glob.Match(absPattern(c.Path, pattern), path)
}

// violation checks whether the dependency from -> to is allowed. Returns
// whether it is a violation and the reason.
func (c *Config) violation(from, to string) (bool, string) {
	for _, key := range orderedKeys(c.BlackList, c.BlackListOrder) {
		if !c.match(key, from) {
			continue
		}
		for _, entry := range c.BlackList[key] {
			for _, p := range c.expand([]string{entry.To}) {
				if c.match(p, to) {
					return true, entry.Reason
				}
			}
		}
	}
	for _, key := range orderedKeys(c.WhiteList, c.WhiteListOrder) {
		if !c.match(key, from) {
			continue
		}
		entry := c.WhiteList[key]
		allowed := false
		for _, p := range c.expand(entry.To) {
			if c.match(p, to) {
				allowed = true
				break
			}
		}
		if !allowed {
			return true, entry.Reason
		}
	}
	return false, ""
}

func (c *Config) rel(path string) string {
	rel, err := filepath.Rel(c.Path, path)
	if err != nil {
		return path
	}
	return rel
}

// Check validates the graph against the configured rules.
func Check(g *graph.Graph, c *Config) error {
	var violations strings.Builder
	failed := false
	for _, n := range g.Nodes {
		for _, child := range n.Children {
			if bad, reason := c.violation(n.Path, child.Path); bad {
				failed = true
				violations.WriteString(fmt.Sprintf("- %s -> %s\n", c.rel(n.Path), c.rel(child.Path)))
				if reason != "" {
					violations.WriteString("  " + reason + "\n")
				}
			}
		}
	}
	var cyclesMsg strings.Builder
	if !c.AllowCircularDependencies {
		cycles := graph.ElementaryCycles(g.Nodes, nil)
		if len(cycles) > 0 {
			failed = true
			cyclesMsg.WriteString("\ndetected circular dependencies:\n")
			for _, cycle := range cycles {
				var names []string
				for _, n := range cycle {
					names = append(names, c.rel(n.Path))
				}
				cyclesMsg.WriteString("- " + strings.Join(names, " -> ") + "\n")
			}
		}
	}
	if !failed {
		return nil
	}
	return errors.New("Check failed, the following dependencies are not allowed:\n" + violations.String() + cyclesMsg.String())
}
