// Package entropy renders the dependency graph as a 3d force directed graph
// inside a self-contained html file.
package entropy

import (
	"bytes"
	"compress/gzip"
	_ "embed"
	"encoding/json"
	"io"
	"os"
	"path/filepath"
	"strings"

	"github.com/deptree-clone/deptree/internal/graph"
)

//go:embed template_prefix.html.gz
var templatePrefix []byte

//go:embed template_suffix.html.gz
var templateSuffix []byte

func gunzip(b []byte) []byte {
	r, err := gzip.NewReader(bytes.NewReader(b))
	if err != nil {
		panic(err)
	}
	out, err := io.ReadAll(r)
	if err != nil {
		panic(err)
	}
	return out
}

type Node struct {
	ID           uint32   `json:"id"`
	IsEntrypoint bool     `json:"isEntrypoint"`
	FileName     string   `json:"fileName"`
	PathBuf      []string `json:"pathBuf"`
	Group        string   `json:"group,omitempty"`
	DirName      string   `json:"dirName"`
	Loc          int      `json:"loc"`
	Size         int      `json:"size"`
}

type Link struct {
	From     uint32 `json:"from"`
	To       uint32 `json:"to"`
	IsCyclic bool   `json:"isCyclic"`
}

type Graph struct {
	Nodes     []Node `json:"nodes"`
	Links     []Link `json:"links"`
	EnableGui bool   `json:"enableGui"`
}

const maxNodeSize = 10

// CyclicEdges computes which edges should be considered cyclic.
func CyclicEdges(g *graph.Graph, entrypoints []*graph.Node) []graph.Edge {
	if len(entrypoints) == 1 {
		edges, _ := graph.DFSCycles(entrypoints, map[*graph.Node]bool{})
		return edges
	}
	var roots []*graph.Node
	for _, n := range g.Nodes {
		if len(n.Parents) == 0 {
			roots = append(roots, n)
		}
	}
	edges, _ := graph.DFSCycles(roots, map[*graph.Node]bool{})
	skip := map[graph.Edge]bool{}
	for _, e := range edges {
		skip[e] = true
	}
	for _, cycle := range graph.ElementaryCycles(g.Nodes, skip) {
		e := graph.Edge{From: cycle[0], To: cycle[1]}
		if !skip[e] {
			skip[e] = true
			edges = append(edges, e)
		}
	}
	return edges
}

func MakeGraph(g *graph.Graph, entrypoints []*graph.Node, enableGui bool) Graph {
	out := Graph{Nodes: []Node{}, Links: []Link{}, EnableGui: enableGui}
	maxLoc := 0
	for _, n := range g.Nodes {
		if n.Info != nil && n.Info.Loc > maxLoc {
			maxLoc = n.Info.Loc
		}
	}
	single := len(entrypoints) == 1
	for _, n := range g.Nodes {
		loc := 0
		group := ""
		rel := ""
		if n.Info != nil {
			loc = n.Info.Loc
			group = n.Info.Package
			rel = n.Info.RelPath
		}
		size := 0
		if maxLoc > 0 {
			size = int(float64(maxNodeSize) * float64(loc) / float64(maxLoc))
		}
		out.Nodes = append(out.Nodes, Node{
			ID:           n.ID,
			IsEntrypoint: single && n == entrypoints[0],
			FileName:     filepath.Base(rel),
			PathBuf:      strings.Split(n.Path, string(filepath.Separator)),
			Group:        group,
			DirName:      filepath.Dir(rel) + "/",
			Loc:          loc,
			Size:         size,
		})
	}
	cyclic := CyclicEdges(g, entrypoints)
	isCyclic := map[graph.Edge]bool{}
	for _, e := range cyclic {
		isCyclic[e] = true
	}
	for _, n := range g.Nodes {
		for _, c := range n.Children {
			if !isCyclic[graph.Edge{From: n, To: c}] {
				out.Links = append(out.Links, Link{From: n.ID, To: c.ID})
			}
		}
	}
	for _, e := range cyclic {
		out.Links = append(out.Links, Link{From: e.From.ID, To: e.To.ID, IsCyclic: true})
	}
	return out
}

func Render(g Graph, path string) error {
	data, err := json.Marshal(g)
	if err != nil {
		return err
	}
	var buf bytes.Buffer
	buf.Write(gunzip(templatePrefix))
	buf.Write(data)
	buf.Write(gunzip(templateSuffix))
	return os.WriteFile(path, buf.Bytes(), 0o600)
}
