package cmd

import (
	"errors"
	"fmt"
	"sort"

	"github.com/spf13/cobra"

	"github.com/deptree-clone/deptree/internal/graph"
	"github.com/deptree-clone/deptree/internal/progress"
)

func ExplainCmd() *cobra.Command {
	var overlapLeft, overlapRight bool
	cmd := &cobra.Command{
		Use:     "explain",
		Short:   "Shows all the dependencies between two parts of the code",
		GroupID: "explain",
		Args:    cobra.ExactArgs(2),
		RunE: func(cmd *cobra.Command, args []string) error {
			if overlapLeft && overlapRight {
				return errors.New("only one of --overlap-left (-l) or --overlap-right (-r) can be used at a time")
			}
			left, err := filesFromArgs(args[:1])
			if err != nil {
				return err
			}
			right, err := filesFromArgs(args[1:])
			if err != nil {
				return err
			}
			cfg, err := loadConfig()
			if err != nil {
				return err
			}
			inLeft := map[string]bool{}
			for _, f := range left {
				inLeft[f] = true
			}
			inRight := map[string]bool{}
			for _, f := range right {
				inRight[f] = true
			}
			if overlapLeft {
				var newRight []string
				for _, f := range right {
					if !inLeft[f] {
						newRight = append(newRight, f)
					} else {
						delete(inRight, f)
					}
				}
				right = newRight
			} else if overlapRight {
				var newLeft []string
				for _, f := range left {
					if !inRight[f] {
						newLeft = append(newLeft, f)
					} else {
						delete(inLeft, f)
					}
				}
				left = newLeft
			}
			if len(left) == 0 {
				return errors.New("at least 1 file must be provided for inferring the language")
			}
			lang, err := inferLang(left, cfg)
			if err != nil {
				return err
			}
			var all []string
			seen := map[string]bool{}
			for _, f := range append(append([]string{}, left...), right...) {
				if !seen[f] {
					seen[f] = true
					all = append(all, f)
				}
			}
			bar := progress.New()
			ig := newIgnorer(cfg)
			g, err := graph.Load(all, lang, func(p string) bool {
				return !seen[p] || ig.Ignore(p)
			}, bar)
			if err != nil {
				return err
			}
			names := graph.DisplayNames(g)
			var lines []string
			for _, n := range g.Nodes {
				if !inLeft[n.Path] {
					continue
				}
				for _, c := range n.Children {
					if inRight[c.Path] {
						lines = append(lines, names[n]+" -> "+names[c])
					}
				}
			}
			sort.Strings(lines)
			for _, l := range lines {
				fmt.Println(l)
			}
			return nil
		},
	}
	cmd.Flags().BoolVarP(&overlapLeft, "overlap-left", "l", false, "When there's an overlap between the files at the left and the right, keep the ones at the left")
	cmd.Flags().BoolVarP(&overlapRight, "overlap-right", "r", false, "When there's an overlap between the files at the left and the right, keep the ones at the right")
	return cmd
}
EOF
