// DisplayNames returns the names used for displaying nodes. If the graph
// contains files from more than one package, names are prefixed with the
// package name.
func DisplayNames(g *Graph) map[*Node]string {
	packages := map[string]bool{}
	for _, n := range g.Nodes {
		if n.Info != nil && n.Info.Package != "" {
			packages[n.Info.Package] = true
		}
	}
	names := map[*Node]string{}
	for _, n := range g.Nodes {
		name := n.Name()
		if len(packages) > 1 && n.Info != nil && n.Info.Package != "" {
			name = strings.TrimPrefix(n.Info.Package, "@") + "@" + name
		}
		names[n] = name
	}
	return names
}
EOF
