			for i < n && src[i] != '\n' {
				i++
			}
		case c == '\'' || c == '"':
			if i+2 < n && src[i+1] == c && src[i+2] == c {
				// triple quoted
				j := i + 3
				end := -1
				for j < n {
					if src[j] == '\\' {
						j += 2
						continue
					}
					if j+2 < n && src[j] == c && src[j+1] == c && src[j+2] == c {
						end = j + 3
						break
					}
					j++
				}
				if end > 0 {
					toks = append(toks, token{tString, src[i:end]})
					i = end
					continue
				}
			}
			j := i + 1
			end := -1
			for j < n && src[j] != '\n' {
				if src[j] == '\\' {
					if j+1 < n && src[j+1] == '\n' {
						break
					}
					j += 2
					continue
				}
				if src[j] == c {
					end = j + 1
					break
				}
				j++
			}
			if end > 0 {
				toks = append(toks, token{tString, src[i:end]})
				i = end
			} else {
				toks = append(toks, token{tPunct, string(c)})
				i++
			}
		case isIdentStart(c):
			j := i + 1
			for j < n && isIdentChar(src[j]) {
				j++
			}
			toks = append(toks, token{tIdent, src[i:j]})
			i = j
		case c >= '0' && c <= '9':
			j := i + 1
			for j < n && isIdentChar(src[j]) {
				j++
			}
			toks = append(toks, token{tOther, src[i:j]})
			i = j
