				i = j
			} else {
				toks = append(toks, token{tPunct, string(c)})
				i++
			}
		}
	}
	return toks
}

// Import represents an `import a.b.c` statement.
type Import struct {
	Path []string
}

// FromImport represents a `from ..a.b import c, d` statement.
type FromImport struct {
	Dots  int
	Path  []string
	Names []string
	All   bool
}

type stmt struct {
	imp  *Import
	from *FromImport
}

type parser struct {
	toks []token
}

func (p *parser) at(i int) *token {
	if i < len(p.toks) {
		return &p.toks[i]
	}
	return nil
}

func (p *parser) ident(i int) bool {
	t := p.at(i)
	return t != nil && t.kind == tIdent
}

func (p *parser) is(i int, kind tokKind, v string) bool {
	t := p.at(i)
	return t != nil && t.kind == kind && t.value == v
}

func (p *parser) dotted(i int) ([]string, int) {
	if !p.ident(i) {
		return nil, -1
	}
	path := []string{p.toks[i].value}
	i++
	for p.is(i, tPunct, ".") && p.ident(i+1) {
		path = append(path, p.toks[i+1].value)
		i += 2
	}
	return path, i
}

func (p *parser) skipNL(i int) int {
	for p.is(i, tNewline, "\n") {
		i++
	}
	return i
}

func (p *parser) name(i int) int {
	if !p.ident(i) {
		return -1
	}
	i++
	if p.is(i, tIdent, "as") && p.ident(i+1) {
		return i + 2
	}
	return i
}

func (p *parser) matchImport(i int) (int, *Import) {
	if !p.is(i, tIdent, "import") {
		return 0, nil
	}
	path, j := p.dotted(i + 1)
	if j < 0 {
		return 0, nil
	}
	return j, &Import{Path: path}
}

func (p *parser) matchFrom(i int) (int, *FromImport) {
	if !p.is(i, tIdent, "from") {
		return 0, nil
	}
	j := i + 1
	f := &FromImport{}
	for p.is(j, tPunct, ".") {
		f.Dots++
		j++
	}
	if path, k := p.dotted(j); k >= 0 {
		f.Path = path
		j = k
	}
	if f.Dots == 0 && len(f.Path) == 0 {
		return 0, nil
	}
	if !p.is(j, tIdent, "import") {
		return 0, nil
	}
	j++
	if p.is(j, tPunct, "*") {
		f.All = true
		return j + 1, f
	}
	if p.is(j, tPunct, "(") {
		k := p.skipNL(j + 1)
		for {
			e := p.name(k)
			if e < 0 {
				break
			}
			f.Names = append(f.Names, p.toks[k].value)
			k = p.skipNL(e)
			if p.is(k, tPunct, ",") {
				k = p.skipNL(k + 1)
				continue
			}
			break
		}
		if len(f.Names) == 0 || !p.is(k, tPunct, ")") {
			return 0, nil
		}
		return k + 1, f
	}
	k := j
	for {
		e := p.name(k)
		if e < 0 {
			break
		}
		f.Names = append(f.Names, p.toks[k].value)
		k = e
		if p.is(k, tPunct, ",") {
			k++
			continue
		}
		break
	}
	if len(f.Names) == 0 {
		return 0, nil
	}
	return k, f
}

func parse(src string) []stmt {
	p := &parser{toks: tokenize(src)}
	var stmts []stmt
	i := 0
	for i < len(p.toks) {
		if end, imp := p.matchImport(i); imp != nil {
			stmts = append(stmts, stmt{imp: imp})
			i = end
			continue
		}
		if end, from := p.matchFrom(i); from != nil {
			stmts = append(stmts, stmt{from: from})
			i = end
			continue
		}
		i++
	}
	return stmts
}
