{"command":"cd /workspace && cat > internal/python/language.go <<'EOF'
package python

import (
	"fmt"
	"os"
	"path/filepath"

	"github.com/deptree-clone/deptree/internal/language"
	"github.com/deptree-clone/deptree/internal/utils"
)

var rootMarkers = []string{"setup.py", "pyproject.toml", "requirements.txt", "poetry.lock"}

type Language struct {
	cfg       *Config
	rootCache map[string]string
}

func NewLanguage(entry string, cfg *Config) (*Language, error) {
	return &Language{cfg: cfg, rootCache: map[string]string{}}, nil
}

// findRoot returns the closest parent folder containing a python project
// marker file, or "" if there is none.
func (l *Language) findRoot(dir string) string {
	if r, ok := l.rootCache[dir]; ok {
		return r
	}
	result := ""
	found := false
	for _, m := range rootMarkers {
		if _, err := os.Stat(filepath.Join(dir, m)); err == nil {
			found = true
			break
		}
	}
	if found {
		result = dir
	} else {
		parent := filepath.Dir(dir)
		if parent != dir {
			result = l.findRoot(parent)
		}
	}
	l.rootCache[dir] = result
	return result
}

type resolvedKind int

const (
	kindNone resolvedKind = iota
	kindFile
	kindDir
)

type resolved struct {
	kind resolvedKind
	path string
}

func resolveIn(dir string, path []string) resolved {
	p := filepath.Join(append([]string{dir}, path...)...)
	if len(path) > 0 && utils.FileExists(p+".py") {
		return resolved{kindFile, p + ".py"}
	}
	if utils.DirExists(p) {
		return resolved{kindDir, p}
	}
	return resolved{}
}

// namesFromDir resolves the names imported from a directory.
func namesFromDir(dir string, names []string, all bool) ([]string, error) {
	init := filepath.Join(dir, "__init__.py")
	hasInit := utils.FileExists(init)
	if !hasInit {
		if all || len(names) == 0 {
			return nil, nil
		}
		f := filepath.Join(dir, names[0]+".py")
		if utils.FileExists(f) {
			return []string{f}, nil
		}
		return nil, fmt.Errorf("cannot import file %s.py from directory %s", names[0], dir)
	}
	if all {
		return []string{init}, nil
	}
	var result []string
	for _, name := range names {
		f := filepath.Join(dir, name+".py")
		if utils.FileExists(f) {
			result = append(result, f)
		} else {
			result = append(result, init)
		}
	}
	return result, nil
}

func (l *Language) searchDirs(fileDir string) []string {
	dirs := []string{fileDir}
	if root := l.findRoot(fileDir); root != "" && root != fileDir {
		dirs = append(dirs, root)
	}
	return dirs
}

func (l *Language) Load(absPath string) (*language.Result, error) {
	content, err := os.ReadFile(absPath)
	if err != nil {
		return nil, err
	}
	dir := filepath.Dir(absPath)
	info := &language.FileInfo{
		AbsPath: absPath,
		Loc:     language.CountLines(content),
	}
	root := l.findRoot(dir)
	info.RelPath = language.RelOrEmpty(root, absPath)
	res := &language.Result{Info: info}
	add := func(paths ...string) {
		res.Deps = append(res.Deps, paths...)
	}
	for _, s := range parse(string(content)) {
		if s.imp != nil {
			for _, d := range l.searchDirs(dir) {
				r := resolveIn(d, s.imp.Path)
				if r.kind == kindFile {
					add(r.path)
					break
				} else if r.kind == kindDir {
					init := filepath.Join(r.path, "__init__.py")
					if utils.FileExists(init) {
						add(init)
					}
					break
				}
			}
			continue
		}
		f := s.from
		if f.Dots > 0 {
			base := dir
			for i := 1; i < f.Dots; i++ {
				base = filepath.Dir(base)
			}
			r := resolveIn(base, f.Path)
			switch r.kind {
			case kindFile:
				add(r.path)
			case kindDir:
				paths, err := namesFromDir(r.path, f.Names, f.All)
				if err != nil {
					res.Errors = append(res.Errors, err)
				} else {
					add(paths...)
				}
			default:
				res.Errors = append(res.Errors, fmt.Errorf("could not resolve relative import from %s to %s", dir, filepath.Join(append([]string{base}, f.Path...)...)))
			}
			continue
		}
		for _, d := range l.searchDirs(dir) {
			r := resolveIn(d, f.Path)
			if r.kind == kindFile {
				add(r.path)
				break
			} else if r.kind == kindDir {
				paths, err := namesFromDir(r.path, f.Names, f.All)
				if err != nil {
					res.Errors = append(res.Errors, err)
				} else {
					add(paths...)
				}
				break
			}
		}
	}
	return res, nil
}
EOF
