{"command":"cd /workspace && cat > internal/rust/parser.go <<'EOF'
package rust

type tokKind int

const (
	tIdent tokKind = iota
	tString
	tPunct
	tOther
)

type token struct {
	kind  tokKind
	value string
}

func isIdentStart(c byte) bool {
	return c == '_' || (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z')
}

func isIdentChar(c byte) bool {
	return isIdentStart(c) || (c >= '0' && c <= '9')
}

func tokenize(src string) []token {
	var toks []token
	n := len(src)
	i := 0
	for i < n {
		c := src[i]
		switch {
		case c == ' ' || c == '\t' || c == '\n' || c == '\r' || c == '\f' || c == '\v':
			i++
		case c == '/' && i+1 < n && src[i+1] == '/':
			for i < n && src[i] != '\n' {
				i++
			}
		case c == '/' && i+1 < n && src[i+1] == '*':
			end := -1
			for j := i + 2; j+1 < n; j++ {
				if src[j] == '*' && src[j+1] == '/' {
					end = j + 2
					break
				}
			}
			if end < 0 {
				toks = append(toks, token{tPunct, "/"})
				i++
			} else {
				i = end
			}
		case c == '"':
			j := i + 1
			end := -1
			for j < n {
				if src[j] == '\\' {
					j += 2
					continue
				}
				if src[j] == '"' {
					end = j + 1
					break
				}
				j++
			}
			if end < 0 {
				toks = append(toks, token{tPunct, "\""})
				i++
			} else {
				toks = append(toks, token{tString, src[i:end]})
				i = end
			}
		case c == '\'':
			// char literal
			if i+2 < n && src[i+1] == '\\' {
				j := i + 2
				for j < n && src[j] != '\'' && src[j] != '\n' && j-i < 12 {
					j++
				}
				if j < n && src[j] == '\'' {
					toks = append(toks, token{tString, src[i : j+1]})
					i = j + 1
					continue
				}
			} else if i+2 < n && src[i+2] == '\'' {
				toks = append(toks, token{tString, src[i : i+3]})
				i += 3
				continue
			}
			toks = append(toks, token{tPunct, "'"})
			i++
		case c == ':' && i+1 < n && src[i+1] == ':':
			toks = append(toks, token{tPunct, "::"})
			i += 2
		case isIdentStart(c):
			j := i + 1
			for j < n && isIdentChar(src[j]) {
				j++
			}
			toks = append(toks, token{tIdent, src[i:j]})
			i = j
		case c >= '0' && c <= '9':
			j := i + 1
			for j < n && isIdentChar(src[j]) {
				j++
			}
			toks = append(toks, token{tOther, src[i:j]})
			i = j
		default:
			if c >= 0x80 {
				j := i + 1
				for j < n && src[j]&0xC0 == 0x80 {
					j++
				}
				toks = append(toks, token{tOther, src[i:j]})
				i = j
			} else {
				toks = append(toks, token{tPunct, string(c)})
				i++
			}
		}
	}
	return toks
}

type stmt struct {
	// mod declaration
	mod string
	// use statement: flattened paths
	uses [][]string
}

type parser struct {
	toks []token
}

func (p *parser) at(i int) *token {
	if i < len(p.toks) {
		return &p.toks[i]
	}
	return nil
}

func (p *parser) ident(i int) bool {
	t := p.at(i)
	return t != nil && t.kind == tIdent
}

func (p *parser) punct(i int, v string) bool {
	t := p.at(i)
	return t != nil && t.kind == tPunct && t.value == v
}

func (p *parser) identV(i int, v string) bool {
	t := p.at(i)
	return t != nil && t.kind == tIdent && t.value == v
}

// useTree parses a use tree at i, returning the flattened paths relative to
// prefix and the index after the tree.
func (p *parser) useTree(i int, prefix []string) ([][]string, int) {
	if p.punct(i, "::") {
		i++
	}
	if p.punct(i, "{") {
		return p.group(i, prefix)
	}
	if p.punct(i, "*") {
		return [][]string{append(append([]string{}, prefix...), "*")}, i + 1
	}
	if !p.ident(i) {
		return nil, -1
	}
	path := append([]string{}, prefix...)
	path = append(path, p.toks[i].value)
	i++
	for p.punct(i, "::") {
		if p.ident(i + 1) {
			path = append(path, p.toks[i+1].value)
			i += 2
			continue
		}
		if p.punct(i+1, "{") {
			return p.group(i+1, path)
		}
		if p.punct(i+1, "*") {
			return [][]string{append(path, "*")}, i + 2
		}
		return nil, -1
	}
	if p.identV(i, "as") {
		if p.ident(i + 1) {
			i += 2
		} else {
			return nil, -1
		}
	}
	return [][]string{path}, i
}

func (p *parser) group(i int, prefix []string) ([][]string, int) {
	if !p.punct(i, "{") {
		return nil, -1
	}
	i++
	var result [][]string
	for {
		if p.punct(i, "}") {
			return result, i + 1
		}
		paths, j := p.useTree(i, prefix)
		if j < 0 {
			return nil, -1
		}
		result = append(result, paths...)
		i = j
		if p.punct(i, ",") {
			i++
			continue
		}
		if p.punct(i, "}") {
			return result, i + 1
		}
		return nil, -1
	}
}

func parse(src string) []stmt {
	p := &parser{toks: tokenize(src)}
	var stmts []stmt
	i := 0
	for i < len(p.toks) {
		if p.identV(i, "use") {
			paths, j := p.useTree(i+1, nil)
			if j >= 0 && p.punct(j, ";") {
				stmts = append(stmts, stmt{uses: paths})
				i = j + 1
				continue
			}
		}
		if p.identV(i, "mod") && p.ident(i+1) && p.punct(i+2, ";") {
			stmts = append(stmts, stmt{mod: p.toks[i+1].value})
			i += 3
			continue
		}
		i++
	}
	return stmts
}
EOF
echo ok"}

