func (l *Language) resolveUse(file string, root *cargoRoot, path []string) (string, error) {
	if len(path) < 2 {
		return "", nil
	}
	first := path[0]
	if first != "crate" && first != "self" && first != "super" {
		return "", nil
	}
	name := path[len(path)-1]
	wrap := func(err error) error {
		return fmt.Errorf("error resolving use statement for name %s: %w", name, err)
	}
	if root == nil {
		return "", nil
	}
	tree := l.modTree(root)
	if tree.err != nil {
		return "", wrap(tree.err)
	}
	var node *modNode
	segs := path[1 : len(path)-1]
	switch first {
	case "crate":
		node = tree.root
	default:
		node = tree.byFile[file]
		if node == nil {
			return "", wrap(errModChain)
		}
		if first == "super" {
			node = node.parent
			if node == nil {
				return "", wrap(errModChain)
			}
		}
	}
	for _, seg := range segs {
		if seg == "super" {
			node = node.parent
			if node == nil {
				return "", wrap(errModChain)
			}
			continue
		}
		if seg == "self" {
			continue
		}
		child, ok := node.children[seg]
		if !ok {
			return "", wrap(errModChain)
		}
		node = child
	}
	return node.file, nil
}

