	root := l.findCargoRoot(dir)
	if root != nil && root.err == nil {
		info.RelPath = language.RelOrEmpty(root.dir, absPath)
		info.Package = root.name
	}
	res := &language.Result{Info: info}
	stmts := parse(string(content))
	l.parseCache[absPath] = stmts
	for _, s := range stmts {
		if s.mod != "" {
			if f := findModFile(dir, s.mod); f != "" {
