package golang

import (
	"errors"
	"fmt"
	"os"
	"strconv"
	"strings"
)

var knownDirectives = map[string]bool{
	"module": true, "go": true, "toolchain": true, "godebug": true, "require": true,
	"exclude": true, "replace": true, "retract": true, "tool": true, "ignore": true,
}

// parseGoMod extracts the module path of a go.mod file. ok is false if the
// go.mod file does not declare a module.
func parseGoMod(path string) (string, bool, error) {
	content, err := os.ReadFile(path)
	if err != nil {
		return "", false, err
	}
	var errs []string
	module := ""
	found := false
	inBlock := false
	for i, rawLine := range strings.Split(string(content), "\n") {
		line := rawLine
		if idx := strings.Index(line, "//"); idx >= 0 {
			line = line[:idx]
		}
		line = strings.TrimSpace(line)
		if line == "" {
			continue
		}
		if inBlock {
			if line == ")" {
				inBlock = false
			}
			continue
		}
		fields := strings.Fields(line)
		directive := fields[0]
		if !knownDirectives[directive] {
			errs = append(errs, fmt.Sprintf("%s:%d: unknown directive: %s", path, i+1, directive))
			continue
		}
		if len(fields) > 1 && fields[len(fields)-1] == "(" {
			inBlock = true
			continue
		}
		switch directive {
		case "module":
			if found {
				errs = append(errs, fmt.Sprintf("%s:%d: repeated module statement", path, i+1))
				continue
			}
			if len(fields) != 2 {
				errs = append(errs, fmt.Sprintf("%s:%d: usage: module module/path", path, i+1))
				continue
			}
			m := fields[1]
			if strings.HasPrefix(m, "\"") {
				if u, err := strconv.Unquote(m); err == nil {
					m = u
				}
			}
			module = m
			found = true
		case "require":
			if len(fields) != 3 {
				errs = append(errs, fmt.Sprintf("%s:%d: usage: require module/path v1.2.3", path, i+1))
			}
		}
	}
	if len(errs) > 0 {
		return "", false, errors.New(strings.Join(errs, "\n"))
	}
	return module, found, nil
}
