package golang

import (
	"fmt"
	"go/ast"
	"go/parser"
	"go/token"
	"os"
	"path/filepath"
	"sort"
	"strconv"
	"strings"

	"github.com/deptree-clone/deptree/internal/language"
	"github.com/deptree-clone/deptree/internal/utils"
)

type dirInfo struct {
	// symbols per package name
	packages map[string]map[string]string
	// merged symbols of all the packages
	all map[string]string
	err error
}

type Language struct {
	root   string
	module string
	dirs   map[string]*dirInfo
	fset   *token.FileSet
}

func NewLanguage(entry string) (language.Language, error) {
	dir := filepath.Dir(entry)
	for {
		gomod := filepath.Join(dir, "go.mod")
		if utils.FileExists(gomod) {
			module, ok, err := parseGoMod(gomod)
			if err != nil {
				return nil, err
			}
			if !ok {
				goModPanic()
			}
			return &Language{
				root:   dir,
				module: module,
				dirs:   map[string]*dirInfo{},
				fset:   token.NewFileSet(),
			}, nil
		}
		parent := filepath.Dir(dir)
		if parent == dir {
			break
		}
		dir = parent
	}
	return nil, fmt.Errorf("no go.mod file found in any parent directory of %s", entry)
}

func declaredSymbols(f *ast.File) []string {
	var names []string
	for _, decl := range f.Decls {
		switch d := decl.(type) {
		case *ast.FuncDecl:
			if d.Recv == nil && d.Name != nil {
				names = append(names, d.Name.Name)
			}
		case *ast.GenDecl:
			for _, spec := range d.Specs {
				switch s := spec.(type) {
				case *ast.TypeSpec:
					names = append(names, s.Name.Name)
				case *ast.ValueSpec:
					for _, n := range s.Names {
						names = append(names, n.Name)
					}
				}
			}
		}
	}
	return names
}

func (l *Language) readDir(dir string) *dirInfo {
	if info, ok := l.dirs[dir]; ok {
		return info
	}
	info := &dirInfo{packages: map[string]map[string]string{}, all: map[string]string{}}
	l.dirs[dir] = info
	entries, err := os.ReadDir(dir)
	if err != nil {
		info.err = err
		return info
	}
	sort.Slice(entries, func(i, j int) bool { return entries[i].Name() < entries[j].Name() })
	for _, e := range entries {
		if e.IsDir() || !strings.HasSuffix(e.Name(), ".go") {
			continue
		}
		path := filepath.Join(dir, e.Name())
		f, err := parser.ParseFile(l.fset, path, nil, parser.SkipObjectResolution)
		if err != nil {
			info.err = err
			return info
		}
		pkg := f.Name.Name
		if info.packages[pkg] == nil {
			info.packages[pkg] = map[string]string{}
		}
		for _, name := range declaredSymbols(f) {
			info.packages[pkg][name] = path
			info.all[name] = path
		}
	}
	return info
}

type importEntry struct {
	// alias is set if the import was renamed
	alias string
	dot   bool
	info  *dirInfo
}

func (l *Language) localDir(importPath string) (string, bool) {
	if importPath == l.module {
		return l.root, true
	}
	if strings.HasPrefix(importPath, l.module+"/") {
		return filepath.Join(l.root, strings.TrimPrefix(importPath, l.module+"/")), true
	}
	return "", false
}

func (l *Language) Load(absPath string) (*language.Result, error) {
	content, err := os.ReadFile(absPath)
	if err != nil {
		return nil, err
	}
	f, err := parser.ParseFile(l.fset, absPath, content, 0)
	if err != nil {
		return nil, err
	}
	info := &language.FileInfo{
		AbsPath: absPath,
		RelPath: language.RelOrEmpty(l.root, absPath),
		Package: f.Name.Name,
		Loc:     language.CountLines(content),
	}
	res := &language.Result{Info: info}

	own := l.readDir(filepath.Dir(absPath))
	if own.err != nil {
		return nil, own.err
	}
	samePkg := own.packages[f.Name.Name]

	var imports []importEntry
	for _, spec := range f.Imports {
		p, err := strconv.Unquote(spec.Path.Value)
		if err != nil {
			continue
		}
		dir, ok := l.localDir(p)
		if !ok {
			continue
		}
		di := l.readDir(dir)
		if di.err != nil {
			res.Errors = append(res.Errors, di.err)
			continue
		}
		entry := importEntry{info: di}
		if spec.Name != nil {
			switch spec.Name.Name {
			case "_":
				continue
			case ".":
				entry.dot = true
			default:
				entry.alias = spec.Name.Name
			}
		}
		imports = append(imports, entry)
	}

	for _, ident := range f.Unresolved {
		if file, ok := samePkg[ident.Name]; ok {
			res.Deps = append(res.Deps, file)
			continue
		}
		for _, imp := range imports {
			if !imp.dot {
				continue
			}
			if file, ok := imp.info.all[ident.Name]; ok {
				res.Deps = append(res.Deps, file)
				break
			}
		}
	}

	ast.Inspect(f, func(n ast.Node) bool {
		sel, ok := n.(*ast.SelectorExpr)
		if !ok {
			return true
		}
		x, ok := sel.X.(*ast.Ident)
		if !ok {
			return true
		}
		for _, imp := range imports {
			if imp.dot {
				continue
			}
			var symbols map[string]string
			if imp.alias != "" {
				if imp.alias == x.Name {
					symbols = imp.info.all
				}
			} else {
				symbols = imp.info.packages[x.Name]
			}
			if symbols == nil {
				continue
			}
			if file, ok := symbols[sel.Sel.Name]; ok {
				res.Deps = append(res.Deps, file)
				break
			}
		}
		return true
	})
	return res, nil
}
