		sel, ok := n.(*ast.SelectorExpr)
		if !ok {
			return true
		}
		x, ok := sel.X.(*ast.Ident)
		if !ok {
			return true
		}
		for _, imp := range imports {
			if imp.dot {
				continue
			}
			var symbols map[string]string
			if imp.alias != "" {
				if imp.alias == x.Name {
					symbols = imp.info.all
				}
			} else {
				symbols = imp.info.packages[x.Name]
			}
			if symbols == nil {
				continue
			}
			if file, ok := symbols[sel.Sel.Name]; ok {
				res.Deps = append(res.Deps, file)
				break
			}
		}
		return true
	})
	return res, nil
