package tree

import (
	"sort"

	"github.com/deptree-clone/deptree/internal/graph"
)

const (
	dirU = 1 << iota
	dirD
	dirL
	dirR
)

const (
	colorNone = iota
	colorGreen
	colorCyan
)

type cell struct {
	dirs  int
	char  rune // explicit char (labels and arrows)
	color int
}

type placed struct {
	node  *graph.Node
	row   int
	x     int
	level int
	name  string
}

func (p *placed) end() int {
	return p.x + len([]rune(p.name)) - 1
}

// Layout is the rendered representation of a tree.
type Layout struct {
	nodes    []*placed
	byNode   map[*graph.Node]*placed
	byRow    map[int]*placed
	children map[*graph.Node][]*graph.Node
	cyclic   map[*graph.Node][]*graph.Node
	base     map[int]int
	rows     int
}

// NewLayout computes the position of every node reachable from root.
func NewLayout(root *graph.Node) *Layout {
	cyclicEdges, _ := graph.DFSCycles([]*graph.Node{root}, map[*graph.Node]bool{})
	isCyclic := map[graph.Edge]bool{}
	l := &Layout{
		byNode:   map[*graph.Node]*placed{},
		byRow:    map[int]*placed{},
		children: map[*graph.Node][]*graph.Node{},
		cyclic:   map[*graph.Node][]*graph.Node{},
		base:     map[int]int{},
	}
	for _, e := range cyclicEdges {
		isCyclic[e] = true
		l.cyclic[e.From] = append(l.cyclic[e.From], e.To)
	}
	// reachable nodes through tree edges
	var order []*graph.Node
	seen := map[*graph.Node]bool{root: true}
	queue := []*graph.Node{root}
	for len(queue) > 0 {
		n := queue[0]
		queue = queue[1:]
		order = append(order, n)
		for _, c := range n.Children {
			if isCyclic[graph.Edge{From: n, To: c}] {
				continue
			}
			l.children[n] = append(l.children[n], c)
			if !seen[c] {
				seen[c] = true
				queue = append(queue, c)
			}
		}
	}
	// longest path levels (the graph without cyclic edges is a DAG)
	levels := map[*graph.Node]int{}
	var topo []*graph.Node
	visited := map[*graph.Node]bool{}
	var visit func(n *graph.Node)
	visit = func(n *graph.Node) {
		visited[n] = true
		for _, c := range l.children[n] {
			if !visited[c] {
				visit(c)
			}
		}
		topo = append(topo, n)
	}
	visit(root)
	for i := len(topo) - 1; i >= 0; i-- {
		n := topo[i]
		for _, c := range l.children[n] {
			if levels[n]+1 > levels[c] {
				levels[c] = levels[n] + 1
			}
		}
	}
	maxLevel := 0
	byLevel := map[int][]*graph.Node{}
	for _, n := range order {
		lv := levels[n]
		byLevel[lv] = append(byLevel[lv], n)
		if lv > maxLevel {
			maxLevel = lv
		}
	}
	row := 0
	base := 0
	for lv := 0; lv <= maxLevel; lv++ {
		nodes := byLevel[lv]
		sort.SliceStable(nodes, func(i, j int) bool { return nodes[i].Name() < nodes[j].Name() })
		if lv > 0 {
			row++
		}
		l.base[lv] = base
		offset := 0
		maxX := base
		for _, n := range nodes {
			p := &placed{node: n, row: row, x: base + offset, level: lv, name: n.Name()}
			if p.x > maxX {
				maxX = p.x
			}
			if len(l.children[n]) > 0 {
				offset++
			}
			l.nodes = append(l.nodes, p)
			l.byNode[n] = p
			l.byRow[row] = p
			row++
		}
		base = maxX + 2
	}
	l.rows = row
	return l
}

type grid struct {
	cells map[[2]int]*cell
}

func newGrid() *grid {
	return &grid{cells: map[[2]int]*cell{}}
}

func (g *grid) at(row, col int) *cell {
	k := [2]int{row, col}
	c, ok := g.cells[k]
	if !ok {
		c = &cell{}
		g.cells[k] = c
	}
	return c
}

func (g *grid) addDirs(row, col, dirs int) {
	if col < 0 || row < 0 {
		return
	}
	c := g.at(row, col)
	c.dirs |= dirs
}

func (g *grid) setChar(row, col int, r rune) {
	if col < 0 || row < 0 {
		return
	}
	c := g.at(row, col)
	c.char = r
}

func (l *Layout) drawTreeEdges(g *grid, parent *placed) {
	children := l.children[parent.node]
	if len(children) == 0 {
		return
	}
	lastRow := 0
	for _, c := range children {
		if p := l.byNode[c]; p.row > lastRow {
			lastRow = p.row
		}
	}
	for r := parent.row + 1; r <= lastRow; r++ {
		dirs := dirU
		if r < lastRow {
			dirs |= dirD
		}
		g.addDirs(r, parent.x, dirs)
	}
	for _, c := range children {
		cp := l.byNode[c]
		g.addDirs(cp.row, parent.x, dirR)
		arrow := l.base[cp.level] - 1
		for col := parent.x + 1; col < arrow; col++ {
			g.addDirs(cp.row, col, dirL|dirR)
		}
		g.setChar(cp.row, arrow, '▷')
	}
}

func (l *Layout) cycleColumn(src, dst *placed) int {
	maxEnd := 0
	for r := dst.row; r <= src.row; r++ {
		if p, ok := l.byRow[r]; ok && p.end() > maxEnd {
			maxEnd = p.end()
		}
	}
	return maxEnd + 1
}

func (l *Layout) drawCycleEdges(g *grid, src *placed) {
	for _, t := range l.cyclic[src.node] {
		dst := l.byNode[t]
		if dst == nil {
			continue
		}
		x := l.cycleColumn(src, dst)
		for col := src.end() + 1; col < x; col++ {
			g.addDirs(src.row, col, dirL|dirR)
		}
		g.addDirs(src.row, x, dirL|dirU)
		for r := dst.row + 1; r < src.row; r++ {
			g.addDirs(r, x, dirU|dirD)
		}
		g.addDirs(dst.row, x, dirL|dirD)
		for col := dst.end() + 2; col < x; col++ {
			g.addDirs(dst.row, col, dirL|dirR)
		}
		g.setChar(dst.row, dst.end()+1, '◁')
	}
}

func dirsChar(d int) rune {
	switch d {
	case dirU | dirD | dirL | dirR:
		return '│'
	case dirU | dirD | dirR:
		return '├'
	case dirU | dirD | dirL:
		return '┤'
	case dirL | dirR | dirU:
		return '┴'
	case dirL | dirR | dirD:
		return '┬'
	case dirU | dirR:
		return '└'
	case dirU | dirL:
		return '┘'
	case dirD | dirR:
		return '┌'
	case dirD | dirL:
		return '┐'
	case dirU | dirD, dirU, dirD:
		return '│'
	case dirL | dirR, dirL, dirR:
		return '─'
	}
	return ' '
}

// Screen is a fully rendered tree.
type Screen struct {
	Rows   [][]rune
	Colors [][]int
}

// Render renders the layout highlighting the node placed at selectedRow.
func (l *Layout) Render(selectedRow int) *Screen {
	g := newGrid()
	for _, p := range l.nodes {
		l.drawTreeEdges(g, p)
	}
	for _, p := range l.nodes {
		l.drawCycleEdges(g, p)
	}
	sel := l.byRow[selectedRow]
	var hl *grid
	if sel != nil {
		hl = newGrid()
		l.drawTreeEdges(hl, sel)
		l.drawCycleEdges(hl, sel)
	}
	maxCol := 0
	for k := range g.cells {
		if k[1] > maxCol {
			maxCol = k[1]
		}
	}
	for _, p := range l.nodes {
		if p.end() > maxCol {
			maxCol = p.end()
		}
	}
	screen := &Screen{}
	childOfSel := map[*graph.Node]bool{}
	if sel != nil {
		for _, c := range l.children[sel.node] {
			childOfSel[c] = true
		}
	}
	for r := 0; r < l.rows; r++ {
		line := make([]rune, maxCol+1)
		colors := make([]int, maxCol+1)
		for c := range line {
			line[c] = ' '
			if cl, ok := g.cells[[2]int{r, c}]; ok {
				if cl.char != 0 {
					line[c] = cl.char
				} else if cl.dirs != 0 {
					line[c] = dirsChar(cl.dirs)
				}
			}
			if hl != nil {
				if cl, ok := hl.cells[[2]int{r, c}]; ok {
					if cl.char != 0 {
						line[c] = cl.char
					} else if cl.dirs != 0 {
						line[c] = dirsChar(cl.dirs)
					}
					colors[c] = colorGreen
				}
			}
		}
		if p, ok := l.byRow[r]; ok {
			color := colorNone
			if p == sel {
				color = colorGreen
			} else if childOfSel[p.node] {
				color = colorCyan
			}
			for i, ch := range []rune(p.name) {
				line[p.x+i] = ch
				colors[p.x+i] = color
			}
		}
		// trim trailing spaces
		end := len(line)
		for end > 0 && line[end-1] == ' ' && colors[end-1] == colorNone {
			end--
		}
		screen.Rows = append(screen.Rows, line[:end])
		screen.Colors = append(screen.Colors, colors[:end])
	}
	return screen
}

// NodeAt returns the node placed at the provided row, if any.
func (l *Layout) NodeAt(row int) *graph.Node {
	if p, ok := l.byRow[row]; ok {
		return p.node
	}
	return nil
}

func (l *Layout) Rows() int {
	return l.rows
}
