			return
		}
		if cur.cursor < cur.scroll {
			cur.scroll = cur.cursor
		}
		if cur.cursor >= cur.scroll+h {
			cur.scroll = cur.cursor - h + 1
		}
		screen := cur.layout.Render(cur.cursor)
		for i := 0; i < h; i++ {
			if i > 0 {
				sb.WriteString("\r\n")
			}
			r := cur.scroll + i
			if r < len(screen.Rows) {
				row := screen.Rows[r]
				colors := screen.Colors[r]
				last := colorNone
				for c := 0; c < len(row) && c < w; c++ {
					if colors[c] != last {
						switch colors[c] {
						case colorGreen:
							sb.WriteString("\x1b[32m")
						case colorCyan:
							sb.WriteString("\x1b[36m")
						default:
							sb.WriteString("\x1b[39m")
						}
