					if cur.cursor > 0 {
						cur.cursor--
					}
				case 4: // ctrl d
					cur.cursor += h / 2
					if cur.cursor > cur.layout.Rows()-1 {
						cur.cursor = cur.layout.Rows() - 1
					}
				case 21: // ctrl u
					cur.cursor -= h / 2
					if cur.cursor < 0 {
						cur.cursor = 0
					}
